259	  private func handle(frame: SessionFrame, connection: SessionConnection) {
260	    switch frame.kind {
261	    case .attach:
262	      handleAttach(payload: frame.payload, connection: connection)
263	    case .input:
264	      guard let identifier = connection.attachedSession, let session = sessions[identifier] else {
265	        return
266	      }
267	      session.appendInput(frame.payload, limit: Self.sessionInputLimit)
268	      session.flushInput()
269	    case .resize:
270	      guard let identifier = connection.attachedSession,
271	        let session = sessions[identifier],
272	        let size = try? SessionResizePayload.decode(frame.payload)
273	      else { return }
274	      guard SessionWindowSizePolicy.isUsable(columns: size.columns, rows: size.rows) else { return }
275	      SessionPTY.resize(
276	        masterDescriptor: session.masterDescriptor, columns: size.columns, rows: size.rows)
277	    case .list:
278	      connection.enqueue(
279	        SessionFrame(
280	          kind: .sessions,
281	          payload: SessionDescriptor.encodeList(sessions.values.map(\.descriptor))))
282	    case .info:
283	      guard let identifier = try? SessionIdentifierPayload.decode(frame.payload) else { return }
284	      let matches = sessions[identifier].map { [$0.descriptor] } ?? []
285	      connection.enqueue(
286	        SessionFrame(kind: .sessions, payload: SessionDescriptor.encodeList(matches)))
287	    case .kill:
288	      let stopped: Bool
289	      if let identifier = try? SessionIdentifierPayload.decode(frame.payload),
290	        let session = sessions[identifier]
291	      {
292	        stopped = endSession(session, status: 0, force: true)
293	      } else {
294	        stopped = true
295	      }
296	      enqueueStopResult(stopped, connection: connection)
297	    case .killAll:
298	      enqueueStopResult(endSessions(Array(sessions.values), status: 0), connection: connection)
299	    case .attached, .output, .exited, .failure, .sessions, .acknowledged:
300	      break
301	    }
302	  }
303	
304	  private func handleAttach(payload: [UInt8], connection: SessionConnection) {
305	    guard let request = try? SessionAttachRequest.decode(payload) else {
306	      connection.enqueue(
307	        SessionFrame(
308	          kind: .failure, payload: SessionTextPayload.encode("malformed attach request")))
309	      connection.closesAfterFlush = true
310	      return
311	    }
312	    guard request.version == SessionProtocolVersion.current else {
313	      connection.enqueue(
314	        SessionFrame(
315	          kind: .failure,
316	          payload: SessionTextPayload.encode(
317	            "this background session is owned by a different version of Workroom; stop it to start a new one"
318	          )))
319	      connection.closesAfterFlush = true
320	      return
321	    }
322	    guard connection.attachedSession == nil else { return }
323	
324	    if let session = sessions[request.identifier] {
325	      attach(session: session, request: request, connection: connection)
326	      return
327	    }
328	    create(request: request, connection: connection)
329	  }
330	
331	  private func attach(
332	    session: PTYSession, request: SessionAttachRequest, connection: SessionConnection
333	  ) {
334	    if let previous = session.clientDescriptor, previous != connection.descriptor {
335	      connections[previous]?.attachedSession = nil
336	      markForClose(previous)
337	    }
338	    session.clientDescriptor = connection.descriptor
339	    session.metadata = request.metadata
340	    connection.attachedSession = session.identifier
341	
342	    if SessionWindowSizePolicy.isUsable(columns: request.columns, rows: request.rows) {
343	      SessionPTY.resize(
344	        masterDescriptor: session.masterDescriptor,
345	        columns: request.columns,
346	        rows: request.rows)
347	    }
348	    connection.enqueue(
349	      SessionFrame(
350	        kind: .attached,
351	        payload: SessionAttachAccepted(
352	          created: false,
353	          shellProcessID: session.processID,
354	          ttyDevice: session.ttyDevice
355	        ).encoded()))
356	    // Synthesize a fresh title (OSC 2) and pwd (OSC 7) from the pty's CURRENT foreground process
357	    // before replaying anything. Both are normally set once by the shell's preexec/prompt hooks —
358	    // one-shot escapes emitted on the PRIMARY screen, before the foreground program (typically)
359	    // switches to the alternate screen — and `SessionReplayBuffer` drops its buffer the moment the
360	    // alternate screen activates, so a reattaching client never sees them; the foreground program
361	    // itself has no reason to re-emit either on the redraw `requestRedraw` forces. Excluding the
362	    // shell's own pgid (`forkpty` makes an idle prompt's foreground group equal `session.processID`)
363	    // keeps an idle reattached pane from showing a phantom "zsh"/"bash" title and stale pwd.
364	    if let group = SessionPTY.foregroundProcessGroup(masterDescriptor: session.masterDescriptor),
365	      group != session.processID
366	    {
367	      // Sanitized before ANY use below — both the log line and the OSC payloads. `name`/`cwd` come
368	      // from OS process introspection (an exec'd argv[0], a directory's real name) and can legally
369	      // contain any byte a filesystem path or exec argument allows, including a raw ESC or BEL. Left
370	      // unsanitized, such a byte would prematurely terminate the OSC 2/7 sequence it's interpolated
371	      // into (from the terminal's perspective) and let the remainder be reinterpreted as fresh,
372	      // attacker-chosen escape/terminal input in the reattaching client.
373	      let name = SessionPTY.executableName(processID: group).map(Self.sanitizedForEscapeSequence)
374	      let cwd = SessionPTY.workingDirectory(processID: group).map(Self.sanitizedForEscapeSequence)
375	      SessionLog.write(
376	        "attach \(session.identifier.uuidString): foreground pgid=\(group) name="
377	          + "\(name ?? "?") cwd=\(cwd ?? "?")")
378	      if let name, !name.isEmpty {
379	        connection.enqueue(
380	          SessionFrame(kind: .output, payload: Array("\u{1B}]2;\(name)\u{07}".utf8)))
381	      }
382	      if let cwd, !cwd.isEmpty {
383	        // Ghostty's OSC 7 handler validates the host against the local machine's hostname before
384	        // accepting the path (`internal_os.hostname.isLocal`) — except for the literal string
385	        // "localhost", which it special-cases as always-local. A locally-forked pty is never
386	        // remote, so that's the simpler, mismatch-proof choice over resolving the real hostname.
387	        connection.enqueue(
388	          SessionFrame(
389	            kind: .output, payload: Array("\u{1B}]7;kitty-shell-cwd://localhost\(cwd)\u{07}".utf8)))
390	      }
391	    } else {
392	      SessionLog.write(
393	        "attach \(session.identifier.uuidString): foreground is the login shell "
394	          + "(pid=\(session.processID)); skipping title/pwd synthesis")
395	    }
396	    enqueueReplay(session: session, connection: connection)
397	    // Query the CURRENT size fresh rather than trusting `request.columns/rows` — those may have
398	    // been rejected as unusable above (a transient tiny size from a not-yet-laid-out surface), in
399	    // which case the redraw must still bump from/to whatever size the session's pty actually has.
400	    //
401	    // The bump happens now (cheap, a single ioctl); the resize-back-and-signal is DEFERRED to the
402	    // poll loop (`processExpiredRedraws`), not done here inline with a blocking sleep — this daemon
403	    // is single-threaded and serves every session across every open project, so sleeping here would
404	    // freeze all of them for the duration, worst case stacking to N × the settle window when many
405	    // persisted tabs reattach at once on relaunch.
406	    if let current = SessionPTY.windowSize(descriptor: session.masterDescriptor) {
407	      SessionPTY.resize(
408	        masterDescriptor: session.masterDescriptor, columns: current.columns,
409	        rows: SessionPTY.bumpedRowCount(current.rows))
410	      pendingRedraws[session.identifier] = PendingRedraw(
411	        deadline: SessionClock.monotonicSeconds() + Self.redrawSettleSeconds,
412	        columns: current.columns, rows: current.rows)
413	    }
414	  }
