416	  private func enqueueReplay(session: PTYSession, connection: SessionConnection) {
417	    let bytes = session.replay.replayBytes
418	    guard !bytes.isEmpty else { return }
419	    SessionLog.write(
420	      "attach \(session.identifier.uuidString): replaying \(bytes.count) bytes: "
421	        + Self.escapedPreview(bytes))
422	    var index = 0
423	    while index < bytes.count {
424	      let end = min(index + Self.replayChunkSize, bytes.count)
425	      connection.enqueue(SessionFrame(kind: .output, payload: Array(bytes[index..<end])))
426	      index = end
427	    }
428	  }
429	
430	  private func create(request: SessionAttachRequest, connection: SessionConnection) {
431	    guard sessions.count < Self.maximumSessions else {
432	      connection.enqueue(
433	        SessionFrame(
434	          kind: .failure,
435	          payload: SessionTextPayload.encode("too many background sessions")))
436	      connection.closesAfterFlush = true
437	      return
438	    }
439	    let invocation = SessionShellIntegration.invocation(
440	      command: request.command,
441	      shell: request.shell,
442	      resourcesDirectory: request.resourcesDirectory,
443	      environment: request.environment)
444	    let size = SessionWindowSizePolicy.createSize(columns: request.columns, rows: request.rows)
445	    guard
446	      let process = SessionPTY.spawn(
447	        invocation: invocation,
448	        workingDirectory: request.workingDirectory,
449	        columns: size.columns,
450	        rows: size.rows)
451	    else {
452	      connection.enqueue(
453	        SessionFrame(
454	          kind: .failure, payload: SessionTextPayload.encode("failed to start the session")))
455	      connection.closesAfterFlush = true
456	      return
457	    }
458	
459	    let session = PTYSession(
460	      identifier: request.identifier,
461	      process: process,
462	      workingDirectory: request.workingDirectory,
463	      replayCapacity: Self.replayCapacity)
464	    session.clientDescriptor = connection.descriptor
465	    session.metadata = request.metadata
466	    sessions[request.identifier] = session
467	    sessionsByMaster[process.masterDescriptor] = request.identifier
468	    connection.attachedSession = request.identifier
469	
470	    connection.enqueue(
471	      SessionFrame(
472	        kind: .attached,
473	        payload: SessionAttachAccepted(
474	          created: true,
475	          shellProcessID: process.processID,
476	          ttyDevice: process.ttyDevice
477	        ).encoded()))
478	  }
