480	  private func handleMaster(_ entry: pollfd, identifier: SessionIdentifier) {
481	    guard let session = sessions[identifier] else { return }
482	    if entry.revents & Int16(POLLOUT) != 0 {
483	      session.flushInput()
484	    }
485	    guard
486	      entry.revents & Int16(POLLIN) != 0
487	        || entry.revents & Int16(POLLHUP) != 0
488	        || entry.revents & Int16(POLLNVAL) != 0
489	    else { return }
490	
491	    readLoop: while true {
492	      switch SessionIO.read(session.masterDescriptor) {
493	      case .bytes(let bytes):
494	        session.replay.append(bytes)
495	        if let descriptor = session.clientDescriptor, let connection = connections[descriptor] {
496	          connection.enqueue(SessionFrame(kind: .output, payload: bytes))
497	        }
498	        if isClientBackedUp(session) { break readLoop }
499	      case .wouldBlock:
500	        break readLoop
501	      case .endOfFile, .failed:
502	        closeMaster(session)
503	        return
504	      }
505	    }
506	  }
507	
508	  private func closeMaster(_ session: PTYSession) {
509	    guard session.masterDescriptor >= 0 else { return }
510	    sessionsByMaster.removeValue(forKey: session.masterDescriptor)
511	    SessionIO.close(session.masterDescriptor)
512	    session.masterDescriptor = -1
513	    session.isEnding = true
514	    SessionPTY.terminate(processID: session.processID)
515	  }
516	
517	  @discardableResult
518	  private func endSession(_ session: PTYSession, status: Int32, force: Bool = false) -> Bool {
519	    closeMaster(session)
520	    guard !force || SessionPTY.forceTerminate(processID: session.processID) else {
521	      SessionLog.write("failed to stop session \(session.identifier.uuidString)")
522	      return false
523	    }
524	    finishSession(session, status: status)
525	    return true
526	  }
527	
528	  private func endSessions(_ endingSessions: [PTYSession], status: Int32) -> Bool {
529	    for session in endingSessions { closeMaster(session) }
530	    let failedProcessIDs = SessionPTY.forceTerminate(processIDs: endingSessions.map(\.processID))
531	    for session in endingSessions where !failedProcessIDs.contains(session.processID) {
532	      finishSession(session, status: status)
533	    }
534	    for session in endingSessions where failedProcessIDs.contains(session.processID) {
535	      SessionLog.write("failed to stop session \(session.identifier.uuidString)")
536	    }
537	    return failedProcessIDs.isEmpty
538	  }
539	
540	  private func finishSession(_ session: PTYSession, status: Int32) {
541	    sessions.removeValue(forKey: session.identifier)
542	    guard let descriptor = session.clientDescriptor, let connection = connections[descriptor]
543	    else { return }
544	    connection.enqueue(
545	      SessionFrame(kind: .exited, payload: SessionExitPayload.encode(status: status)))
546	    connection.attachedSession = nil
547	    connection.closesAfterFlush = true
548	    session.clientDescriptor = nil
549	  }
550	
551	  private func enqueueStopResult(_ stopped: Bool, connection: SessionConnection) {
552	    let frame =
553	      stopped
554	      ? SessionFrame(kind: .acknowledged)
555	      : SessionFrame(
556	        kind: .failure, payload: SessionTextPayload.encode("failed to stop one or more sessions"))
557	    connection.enqueue(frame)
558	  }
559	
560	  private func reapChildren() {
561	    while true {
562	      var status: Int32 = 0
563	      let processID = waitpid(-1, &status, WNOHANG)
564	      guard processID > 0 else { return }
565	      guard let session = sessions.values.first(where: { $0.processID == processID }) else {
566	        continue
567	      }
568	      endSession(session, status: Self.exitCode(status))
569	    }
570	  }
571	
572	  static func exitCode(_ status: Int32) -> Int32 {
573	    let terminationSignal = status & 0o177
574	    if terminationSignal == 0 { return (status >> 8) & 0xFF }
575	    if terminationSignal == 0o177 { return 0 }
576	    return 128 + terminationSignal
577	  }
578	
579	  /// Renders bytes for a log line: printable ASCII passes through, `ESC` becomes `<ESC>` (so
580	  /// escape-sequence boundaries are visible at a glance), everything else becomes `\xNN`. Capped so
581	  /// one attach with a large buffer can't blow up the log file.
582	  private static func escapedPreview(_ bytes: [UInt8], limit: Int = 2048) -> String {
583	    let hexDigits = Array("0123456789ABCDEF")
584	    var result = ""
585	    for byte in bytes.prefix(limit) {
586	      switch byte {
587	      case 0x1B:
