106	    var mib: [Int32] = [CTL_KERN, KERN_PROCARGS2, processID]
107	    var size = 0
108	    guard sysctl(&mib, 3, nil, &size, nil, 0) == 0, size > 4 else { return nil }
109	    var buffer = [UInt8](repeating: 0, count: size)
110	    guard sysctl(&mib, 3, &buffer, &size, nil, 0) == 0, size > 4 else { return nil }
