115	    // Layout: argc, then the exec path (NUL-terminated), then NUL padding, then argv[0..argc-1]
116	    // each NUL-terminated. Skip the exec path and padding to reach argv[0].
117	    var offset = 4
118	    while offset < size, buffer[offset] != 0 { offset += 1 }
119	    while offset < size, buffer[offset] == 0 { offset += 1 }
120	    guard offset < size else { return nil }
121	
122	    let start = offset
123	    while offset < size, buffer[offset] != 0 { offset += 1 }
124	    guard offset > start else { return nil }
125	    let argv0 = String(decoding: buffer[start..<offset], as: UTF8.self)
126	    guard let lastSlash = argv0.lastIndex(of: "/") else { return argv0 }
127	    // A trailing slash (argv0 == "foo/") makes this slice empty — nil, not "", so a caller's
128	    // `if let name` doesn't pass through and synthesize a blank title.
129	    let basename = argv0[argv0.index(after: lastSlash)...]
